package org.jlinalg.cli;

import java.io.*;
import java.nio.charset.StandardCharsets;
import java.nio.file.*;
import java.util.*;
import java.util.stream.Stream;
import java.util.zip.GZIPInputStream;
import org.jlinalg.sequence.*;
import org.junit.jupiter.api.Test;
import org.junit.jupiter.api.io.TempDir;
import org.junit.jupiter.params.ParameterizedTest;
import org.junit.jupiter.params.provider.MethodSource;
import static org.junit.jupiter.api.Assertions.*;

class SignacCoverageTest {
    @TempDir Path temp;
    private static Map<?,?> object(Object x){return (Map<?,?>)x;}
    private static List<?> list(Object x){return (List<?>)x;}
    private static int integer(Object x){return ((Number)x).intValue();}
    private static double number(Object x){if(x instanceof Number n)return n.doubleValue();return switch(x.toString()){case "NA","NaN"->Double.NaN;case "Inf"->Double.POSITIVE_INFINITY;case "-Inf"->Double.NEGATIVE_INFINITY;default->throw new IllegalArgumentException("Unknown source kind");};}
    private static final class Fixture {
        static final Map<?,?> DATA=load();
        static final Map<?,?> EDGES=loadEdges();
        static Map<?,?> load(){try(var raw=SignacCoverageTest.class.getResourceAsStream("/org/jlinalg/sequence/signac-coverage/controls.json.gz")){assertNotNull(raw);try(var in=new GZIPInputStream(raw)){return object(SimpleJson.parse(new String(in.readAllBytes(),StandardCharsets.UTF_8)));}}catch(IOException e){throw new UncheckedIOException(e);}}
        static Map<?,?> loadEdges(){try(var raw=SignacCoverageTest.class.getResourceAsStream("/org/jlinalg/sequence/signac-coverage/edges-v2.json.gz")){assertNotNull(raw);try(var in=new GZIPInputStream(raw)){return object(SimpleJson.parse(new String(in.readAllBytes(),StandardCharsets.UTF_8)));}}catch(IOException e){throw new UncheckedIOException(e);}}
    }
    static Stream<Object> sampling(){return list(Fixture.DATA.get("sampling")).stream().map(x->x);}
    @ParameterizedTest @MethodSource("sampling") void originalRFixedSampling(Object raw){var r=object(raw);var random=new SignacCoverageSampling(integer(r.get("seed")));for(Object v:list(r.get("draws"))){int[] expected=list(v).stream().mapToInt(x->integer(x)-1).toArray();assertArrayEquals(expected,random.sample(integer(r.get("n")),integer(r.get("size"))));}}
    static Stream<Object> coverage(){return list(Fixture.DATA.get("coverage")).stream().map(x->x);}
    @ParameterizedTest @MethodSource("coverage") void originalCoverageTrack(Object raw){var row=object(raw);var input=object(row.get("input"));var expected=object(object(row.get("result")).get("value"));
        List<String> cellGroups=list(input.get("groups")).stream().map(String.class::cast).toList();List<String> groups=cellGroups.stream().distinct().toList();int width=integer(input.get("end"))-integer(input.get("start"))+1;long[][] counts=new long[groups.size()][width];
        var matrix=list(input.get("counts"));for(int c=0;c<cellGroups.size();c++)for(int j=0;j<width;j++)counts[groups.indexOf(cellGroups.get(c))][j]+=integer(list(matrix.get(c)).get(j));
        Map<String,Double> factors=new LinkedHashMap<>();for(var e:object(input.get("group_scale_factors")).entrySet())factors.put((String)e.getKey(),number(e.getValue()));
        var options=new SignacCoverage.Options(input.get("window")==null?null:integer(input.get("window")),number(input.get("downsample_rate")),integer(input.get("maximum_downsample")),input.get("ymax"),2000000,250000000);
        var actual=SignacCoverage.track(groups,counts,integer(input.get("start")),factors,number(input.get("scale_factor")),options,()->false);var rows=list(expected.get("rows"));assertEquals(rows.size(),actual.points().size());
        // The original numeric ymax is in its label. ggplot flips an empty -Inf limit to +Inf.
        String label=(String)expected.get("y_label");if(label.endsWith(" - -Inf)")){assertEquals(Double.NEGATIVE_INFINITY,actual.ymax());assertEquals(Double.POSITIVE_INFINITY,number(list(expected.get("y_limits")).get(1)));}
        else assertNumber(number(list(expected.get("y_limits")).get(1)),actual.ymax());
        for(int i=0;i<rows.size();i++){var e=object(rows.get(i));var a=actual.points().get(i);assertEquals(e.get("group"),a.group());assertEquals(integer(e.get("position")),a.position());assertEquals((long)integer(e.get("count")),a.count());assertNumber(number(e.get("norm.value")),a.normalized());assertNumber(number(e.get("coverage")),a.coverage());}
    }
    static Stream<Object> scaling(){return list(Fixture.DATA.get("scaling")).stream().map(x->x);}
    @ParameterizedTest @MethodSource("scaling") void originalObjectScaling(Object raw){var row=object(raw);var input=object(row.get("input"));List<?> ids=list(input.get("cells")),groups=list(input.get("groups")),counts=list(input.get("n_counts"));
        if(list(input.get("groups_missing")).contains(Boolean.TRUE)){assertThrows(IllegalArgumentException.class,()->new SignacCoverage.Cell(ids.get(0).toString(),null,1));return;}
        List<SignacCoverage.Cell> cells=new ArrayList<>();for(int i=0;i<ids.size();i++)cells.add(new SignacCoverage.Cell((String)ids.get(i),(String)groups.get(i),number(counts.get(i))));
        var actual=SignacCoverage.scaling(cells,input.get("levels")==null?null:list(input.get("levels")).stream().map(String.class::cast).toList(),null);var expected=object(object(row.get("result")).get("value"));
        assertEquals(list(expected.get("average_names")),actual.averageNames());assertEquals(list(expected.get("cell_counts")).stream().map(x->((Number)x).longValue()).toList(),actual.cellCounts());
        assertEquals(list(expected.get("factors")).size(),actual.factors().size());for(int i=0;i<actual.factors().size();i++)assertNumber(number(list(expected.get("factors")).get(i)),actual.factors().get(i));assertNumber(number(expected.get("default_scale_factor")),actual.scaleFactor());
    }
    static Stream<Object> cut(){return list(Fixture.DATA.get("cut")).stream().map(x->x);}
    @ParameterizedTest @MethodSource("cut") void originalCutMatrixEndpoints(Object raw)throws Exception{var row=object(raw);var input=object(row.get("input"));Path file=temp.resolve("fragments.tsv");Files.writeString(file,(String)input.get("fragments"));List<SignacCoverage.Cell> cells=list(input.get("cells")).stream().map(x->new SignacCoverage.Cell((String)x,(String)x,1)).toList();List<SignacFragments.Cell> map=new ArrayList<>();for(var e:object(input.get("map")).entrySet())map.add(new SignacFragments.Cell((String)e.getKey(),(String)e.getValue()));
        var actual=SignacCoverage.cuts(List.of(new SignacFragments.Source(file,map)),cells,new SignacFragments.Region("chr1",integer(input.get("start")),integer(input.get("end"))),100000,SignacFragments.Limits.defaults(),()->false);var expected=object(object(row.get("result")).get("value"));assertEquals(list(expected.get("cells")),actual.groups());var matrix=actual.counts();for(int i=0;i<matrix.length;i++)assertArrayEquals(list(list(expected.get("values")).get(i)).stream().mapToLong(x->((Number)x).longValue()).toArray(),matrix[i]);
    }
    static Stream<Object> annotation(){return list(Fixture.DATA.get("annotations")).stream().map(x->x);}
    @ParameterizedTest @MethodSource("annotation") void originalAnnotationGeometry(Object raw){var row=object(raw);var input=object(row.get("input"));List<SignacCoverageAnnotations.Annotation> annotation=new ArrayList<>();for(Object x:list(input.get("annotation"))){var a=object(x);annotation.add(new SignacCoverageAnnotations.Annotation((String)a.get("chromosome"),integer(a.get("start")),integer(a.get("end")),(String)a.get("strand"),(String)a.get("gene_name"),(String)a.get("tx_id"),(String)a.get("gene_biotype"),(String)a.get("type")));}
        var result=SignacCoverageAnnotations.layout(annotation,new SignacFragments.Region("chr1",integer(input.get("start")),integer(input.get("end"))),(Boolean)input.get("collapse_transcripts"),100000,100000,()->false);var expected=object(object(row.get("result")).get("value"));if(Boolean.TRUE.equals(expected.get("empty"))){assertTrue(result.labels().isEmpty());return;}
        segments(list(expected.get("exons")),result.exons());segments(list(expected.get("plus")),result.plus());segments(list(expected.get("minus")),result.minus());var labels=list(expected.get("labels"));assertEquals(labels.size(),result.labels().size());for(int i=0;i<labels.size();i++){var e=object(labels.get(i));var a=result.labels().get(i);segment(e,a.body());assertNumber(number(e.get("width")),a.width());assertNumber(number(e.get("position")),a.position());}
    }
    private static void segments(List<?> expected,List<SignacCoverageAnnotations.Segment> actual){assertEquals(expected.size(),actual.size());for(int i=0;i<expected.size();i++)segment(object(expected.get(i)),actual.get(i));}
    private static void segment(Map<?,?> e,SignacCoverageAnnotations.Segment a){assertEquals(e.get("seqnames"),a.chromosome());assertNumber(number(e.get("start")),a.start());assertNumber(number(e.get("end")),a.end());assertEquals(e.get("strand"),a.strand());assertEquals(e.get("gene_name"),a.geneName());assertEquals(e.get("tx_id"),a.transcriptId());assertEquals(e.get("gene_biotype"),a.biotype());assertEquals(e.get("type"),a.type());assertEquals(integer(e.get("dodge")),a.dodge());}
    private static void assertNumber(double expected,double actual){if(!Double.isFinite(expected))assertEquals(expected,actual);else assertEquals(expected,actual,2e-12*Math.max(1,Math.abs(expected)));}
    static Stream<Object> heterogeneousScaling(){return list(Fixture.EDGES.get("scaling")).stream().map(x->x);}
    @ParameterizedTest @MethodSource("heterogeneousScaling") void originalHeterogeneousFactorRecycling(Object raw){var row=object(raw);List<?> cells=list(row.get("cells")),groups=list(row.get("groups")),counts=list(row.get("n_counts"));List<SignacCoverage.Cell> metadata=new ArrayList<>();for(int i=0;i<cells.size();i++)metadata.add(new SignacCoverage.Cell((String)cells.get(i),(String)groups.get(i),number(counts.get(i))));var actual=SignacCoverage.scaling(metadata,row.get("levels")==null?null:list(row.get("levels")).stream().map(String.class::cast).toList(),null);var expected=object(object(row.get("result")).get("value"));for(int i=0;i<actual.factors().size();i++)assertNumber(number(list(expected.get("factors")).get(i)),actual.factors().get(i));assertNumber(number(expected.get("scale_factor")),actual.scaleFactor());}
    static Stream<Object> sourcePruning(){return list(Fixture.EDGES.get("pruning")).stream().map(x->x);}
    @ParameterizedTest @MethodSource("sourcePruning") void originalPersistentChromosomePruning(Object raw)throws Exception{var row=object(raw);var expected=object(object(row.get("result")).get("value"));Path present=temp.resolve("present.tsv"),missing=temp.resolve("missing.tsv");Files.writeString(present,(String)Fixture.EDGES.get("fragments"));Files.writeString(missing,"chr2\t10\t20\ta\t1\n");List<SignacFragments.Cell> mapping=new ArrayList<>();for(var e:object(Fixture.EDGES.get("map")).entrySet())mapping.add(new SignacFragments.Cell((String)e.getKey(),(String)e.getValue()));List<SignacFragments.Source> sources=list(row.get("order")).stream().map(x->new SignacFragments.Source(x.equals("present")?present:missing,mapping)).toList();var cells=list(Fixture.EDGES.get("cells")).stream().map(x->new SignacCoverage.Cell((String)x,(String)x,1)).toList();var region=new SignacFragments.Region("chr1",100,120);
        if(Boolean.TRUE.equals(expected.get("null"))){assertThrows(IOException.class,()->SignacCoverage.cuts(sources,cells,region,1000,SignacFragments.Limits.defaults(),()->false));return;}var actual=SignacCoverage.cuts(sources,cells,region,1000,SignacFragments.Limits.defaults(),()->false).counts();for(int i=0;i<actual.length;i++)assertArrayEquals(list(list(expected.get("cut")).get(i)).stream().mapToLong(x->((Number)x).longValue()).toArray(),actual[i]);}
    static Stream<Object> fullOriginal(){return list(Fixture.EDGES.get("full")).stream().map(x->x);}
    @ParameterizedTest @MethodSource("fullOriginal") void completeOriginalCoveragePlotData(Object raw)throws Exception{var row=object(raw);var expected=object(object(row.get("result")).get("value"));Files.writeString(temp.resolve("fragments.tsv"),(String)Fixture.EDGES.get("fragments"));var metadata=new StringBuilder("cell\tgroup\tn_count\n");var map=new StringBuilder("cell\tbarcode\n");var cells=list(Fixture.EDGES.get("cells"));var groups=list(Fixture.EDGES.get("groups"));var counts=list(expected.get("source_n_counts"));var mapping=object(Fixture.EDGES.get("map"));for(int i=0;i<cells.size();i++){metadata.append(cells.get(i)).append('\t').append(groups.get(i)).append('\t').append(number(counts.get(i))).append('\n');map.append(cells.get(i)).append('\t').append(mapping.get(cells.get(i))).append('\n');}Files.writeString(temp.resolve("cells.tsv"),metadata);Files.writeString(temp.resolve("map.tsv"),map);
        var r=SignacCoverageContractsTest.request();r.put("source_profile","Signac-"+row.get("version"));r.put("window",1);r.put("downsample_rate",1);r.put("sources",List.of(Map.of("fragments","fragments.tsv","map","map.tsv")));Path request=temp.resolve("request.json");SeuratDifferentialContracts.json(request,r);var log=new ByteArrayOutputStream();var stream=new PrintStream(log,true,StandardCharsets.UTF_8);assertEquals(0,SignacCoverageCli.run(new String[]{"--request",request.toString()},stream,stream),log.toString(StandardCharsets.UTF_8));
        List<String> lines=Files.readAllLines(temp.resolve("result/coverage.tsv"));var rows=list(expected.get("rows"));assertEquals(rows.size()+1,lines.size());for(int i=0;i<rows.size();i++){String[] fields=lines.get(i+1).split("\t");var e=object(rows.get(i));assertEquals(e.get("group"),fields[0]);assertEquals(integer(e.get("position")),Integer.parseInt(fields[1]));assertEquals(integer(e.get("count")),Integer.parseInt(fields[2]));assertNumber(number(e.get("norm.value")),Double.parseDouble(fields[3]));assertNumber(number(e.get("coverage")),Double.parseDouble(fields[4]));}}
    @Test void explicitCapacitiesCancellationAndAmbiguousCellsAreRefused()throws Exception{var cells=List.of(new SignacCoverage.Cell("c","A",1));assertThrows(IllegalArgumentException.class,()->SignacCoverage.scaling(List.of(cells.get(0),cells.get(0)),null,null));assertThrows(IllegalArgumentException.class,()->new SignacCoverage.Options(0,1,3000,null,100,100));assertThrows(java.util.concurrent.CancellationException.class,()->SignacCoverage.track(List.of("A"),new long[][]{{1,2}},1,Map.of("A",1.0),1,SignacCoverage.Options.defaults(),()->true));assertThrows(IllegalArgumentException.class,()->SignacCoverage.track(List.of("A"),new long[][]{{1,2}},1,Map.of("A",1.0),1,new SignacCoverage.Options(1,1,3,null,1,100),()->false));}
}
